mapper.update:

    update configuration_match_template_event


            event_audit_time = #{item.eventAuditTime,jdbcType=INTEGER},


            event_settlement_time = #{item.eventSettlementTime,jdbcType=INTEGER},


            modify_time = #{item.modifyTime},


    where standard_match_id = #{item.standardMatchId,jdbcType=BIGINT} and event_code = #{item.eventCode,jdbcType=VARCHAR}

;
